+```javascript
+// ===== 通用工具函数 =====
+
+// 数据缩放：以均线为中轴放大偏离值
+function scaleOverlayData(data, scale) {
+    var valid = data.filter(function(v) { return v !== null && v !== undefined; });
+    if (!valid.length) return data;
+    var ma = valid.reduce(function(a, b) { return a + b; }, 0) / valid.length;
+    return data.map(function(v) { return v === null ? null : ma + (v - ma) * scale; });
+}
+
+// 数字格式化：最多两位小数
+function formatNumber(v) {
+    if (v === null || v === undefined) return '-';
+    if (typeof v !== 'number') return v;
+    return parseFloat(v.toFixed(2)).toString();
+}
+
+// 大数字格式化：万/亿单位 + 两位小数
+function formatBigNumber(v) {
+    if (v === null || v === undefined || v === 0) return '-';
+    var abs = Math.abs(v);
+    if (abs >= 1e8) return (v / 1e8).toFixed(2) + '亿';
+    if (abs >= 1e4) return (v / 1e4).toFixed(2) + '万';
+    return formatNumber(v);
+}
+
+// 构建沪深300 series（通用）
+function buildHS300Series(hs300Data, dates, scale) {
+    var scaled = scaleOverlayData(hs300Data, scale);
+    var data = scaled.map(function(v, i) {
+        return v !== null ? [dates[i], v] : null;
+    }).filter(function(v) { return v !== null; });
+    var validHS = hs300Data.filter(function(v) { return v !== null; });
+    var hsMA = validHS.length > 0 ? validHS.reduce(function(a, b) { return a + b; }, 0) / validHS.length : 0;
+    return {
+        name: '沪深300', type: 'line', data: scaled,
+        yAxisIndex: 1, smooth: true, symbol: 'diamond', symbolSize: 5,
+        lineStyle: { width: 2, color: '#e74c3c', type: 'dashed' },
+        itemStyle: { color: '#e74c3c' }, z: 10,
+        markLine: {
+            symbol: 'none',
+            lineStyle: { color: '#e74c3c44', type: 'dotted' },
+            data: [{ yAxis: hsMA, label: { formatter: 'MA: ' + hsMA.toFixed(0), color: '#e74c3c88' } }]
+        }
+    };
+}
+
+// 构建ETF series（通用）
+function buildETFSeries(etfCode, dates, color) {
+    var etf = DATA.etf.etfs[etfCode];
+    if (!etf) return null;
+    var data = etf.pct.map(function(v, i) {
+        return v !== null ? [dates[i], v] : null;
+    }).filter(function(v) { return v !== null; });
+    return {
+        name: etf.name + '(' + etf.sector + ')', type: 'line', data: data,
+        yAxisIndex: 1, smooth: true, symbol: 'none',
+        lineStyle: { width: 1.5, type: 'dotted', opacity: 0.8, color: color },
+        emphasis: { focus: 'series' }
+    };
+}
+
+// 创建控件HTML并插入到section中
