+Create `scripts/init_ai_analysis_table.py`:
+
+```python
+# -*- coding: utf-8 -*-
+"""
+初始化 ai_analysis_cache 表
+用法: python scripts/init_ai_analysis_table.py
+"""
+import sqlite3
+from pathlib import Path
+
+DB_PATH = Path(__file__).parent.parent / 'data' / 'kpl_dashboard.db'
+
+def init_ai_analysis_table():
+    conn = sqlite3.connect(DB_PATH)
+    conn.executescript("""
+    CREATE TABLE IF NOT EXISTS ai_analysis_cache (
+        id INTEGER PRIMARY KEY AUTOINCREMENT,
+        chart_id TEXT NOT NULL,
+        chart_title TEXT NOT NULL,
+        analysis_date TEXT NOT NULL,
+        data_hash TEXT,
+        analysis_text TEXT,
+        summary TEXT,
+        confidence REAL DEFAULT 0,
+        agent_name TEXT,
+        analysis_mode TEXT,
+        created_at TEXT NOT NULL,
+        updated_at TEXT,
+        UNIQUE(chart_id, analysis_date, data_hash)
+    );
+    CREATE INDEX IF NOT EXISTS idx_ai_cache_chart_date ON ai_analysis_cache(chart_id, analysis_date);
+    """)
+    conn.commit()
+    conn.close()
+    print("ai_analysis_cache 表创建成功")
+
+if __name__ == '__main__':
+    init_ai_analysis_table()
+```
