+// 极简Markdown渲染
+function renderMarkdown(md) {
+    if (!md) return '<p style="color:#666;">无内容</p>';
+    var html = md
+        .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
+        .replace(/^## (.+)$/gm, '<h2>$1</h2>')
+        .replace(/^### (.+)$/gm, '<h3>$1</h3>')
+        .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
+        .replace(/^- (.+)$/gm, '<li>$1</li>')
+        .replace(/(<li>.+<\/li>\n?)+/g, function(m) { return '<ul>' + m + '</ul>'; })
+        .replace(/\n\n/g, '</p><p>')
+        .replace(/^(?!<[hul])(.+)$/gm, '<p>$1</p>');
+    return html;
+}
