+```python
+# -*- coding: utf-8 -*-
+"""
+从SQLite数据库提取图表数据，构造结构化摘要供LLM分析
+"""
+import sqlite3
+import json
+from pathlib import Path
+from datetime import datetime, timedelta
+
+DB_PATH = Path(__file__).parent.parent / 'data' / 'kpl_dashboard.db'
+
+CHART_META = {
+    'strength': {'title': '板块强度分析', 'table': 'sector_strength'},
+    'strength_pie': {'title': '板块强度分布', 'table': 'sector_strength'},
+    'new_high': {'title': '百日新高分析', 'table': 'new_high'},
+    'sector_new_high': {'title': '百日新高板块', 'table': 'sector_new_high'},
+    'new_high_pie': {'title': '百日新高分布', 'table': 'sector_new_high'},
+    'emotion_limit': {'title': '上涨与下跌', 'table': 'market_sentiment'},
+    'emotion_premium': {'title': '涨停溢价与炸板率', 'table': 'market_sentiment'},
+    'emotion_ladder': {'title': '连板高度与一字板', 'table': 'ladder_data'},
+    'limit_up_pie': {'title': '涨停分布', 'table': 'sector_sentiment'},
+    'limit_up_stocks': {'title': '涨停个股', 'table': 'sector_stock_mapping'},
+}
+
+
+def extract(chart_id, analysis_date):
+    """提取图表数据，返回结构化摘要字典"""
+    conn = sqlite3.connect(str(DB_PATH))
+    try:
+        if chart_id == 'strength':
+            return _extract_strength(conn, analysis_date)
+        elif chart_id == 'strength_pie':
+            return _extract_strength_pie(conn, analysis_date)
+        elif chart_id == 'new_high':
+            return _extract_new_high(conn, analysis_date)
+        elif chart_id == 'sector_new_high':
+            return _extract_sector_new_high(conn, analysis_date)
+        elif chart_id == 'new_high_pie':
+            return _extract_new_high_pie(conn, analysis_date)
+        elif chart_id == 'emotion_limit':
+            return _extract_emotion_limit(conn, analysis_date)
+        elif chart_id == 'emotion_premium':
+            return _extract_emotion_premium(conn, analysis_date)
+        elif chart_id == 'emotion_ladder':
+            return _extract_emotion_ladder(conn, analysis_date)
+        elif chart_id == 'limit_up_pie':
+            return _extract_limit_up_pie(conn, analysis_date)
+        elif chart_id == 'limit_up_stocks':
+            return _extract_limit_up_stocks(conn, analysis_date)
+        else:
+            return {'error': f'Unknown chart_id: {chart_id}'}
+    finally:
+        conn.close()
+
+
+def _get_recent_dates(conn, table, date_col, analysis_date, days=30):
+    """获取最近N天的日期列表"""
+    rows = conn.execute(
+        f"SELECT DISTINCT {date_col} FROM {table} WHERE {date_col} <= ? ORDER BY {date_col} DESC LIMIT ?",
+        (analysis_date, days)
+    ).fetchall()
+    return [r[0] for r in rows]
+
+
+def _extract_strength(conn, analysis_date):
+    dates = _get_recent_dates(conn, 'sector_strength', 'date', analysis_date, 30)
+    if not dates:
+        return {'error': '无板块强度数据'}
+    
+    # 最新日期Top10
+    latest = dates[0]
+    top_rows = conn.execute(
+        "SELECT sector_name, strength FROM sector_strength WHERE date = ? ORDER BY ABS(strength) DESC LIMIT 10",
+        (latest,)
+    ).fetchall()
+    
+    # 30天Top5板块的均值趋势
+    top5_names = [r[0] for r in top_rows[:5]]
+    trend_data = {}
+    for name in top5_names:
+        rows = conn.execute(
+            "SELECT date, strength FROM sector_strength WHERE sector_name = ? AND date >= ? ORDER BY date",
+            (name, dates[-1] if dates else analysis_date)
+        ).fetchall()
+        values = [r[1] for r in rows]
+        if values:
+            avg = sum(values) / len(values)
+            trend = 'up' if values[-1] > values[0] else 'down'
+            trend_data[name] = {'avg': round(avg, 2), 'latest': values[-1], 'trend': trend, 'count': len(values)}
+    
+    return {
+        'chart_id': 'strength',
+        'title': '板块强度分析',
+        'date_range': f"{dates[-1]} ~ {dates[0]}",
+        'data_points': len(dates),
+        'latest_date': latest,
+        'top10': [{'name': r[0], 'strength': round(r[1], 2)} for r in top_rows],
+        'top5_trend': trend_data,
+    }
+
+
+def _extract_strength_pie(conn, analysis_date):
+    dates = _get_recent_dates(conn, 'sector_strength', 'date', analysis_date, 30)
+    if not dates:
+        return {'error': '无数据'}
+    latest = dates[0]
+    rows = conn.execute(
+        "SELECT sector_name, strength FROM sector_strength WHERE date = ? ORDER BY strength DESC",
+        (latest,)
+    ).fetchall()
+    positive = [r for r in rows if r[1] > 0]
+    negative = [r for r in rows if r[1] < 0]
+    return {
+        'chart_id': 'strength_pie',
+        'title': '板块强度分布',
+        'latest_date': latest,
+        'positive_count': len(positive),
+        'negative_count': len(negative),
+        'top5_positive': [{'name': r[0], 'strength': round(r[1], 2)} for r in positive[:5]],
+        'top5_negative': [{'name': r[0], 'strength': round(r[1], 2)} for r in negative[:5]],
+        'total_positive_sum': round(sum(r[1] for r in positive), 2),
+        'total_negative_sum': round(sum(r[1] for r in negative), 2),
+    }
+
+
+def _extract_new_high(conn, analysis_date):
+    dates = _get_recent_dates(conn, 'new_high', 'date', analysis_date, 60)
+    if not dates:
+        return {'error': '无数据'}
+    rows = conn.execute(
+        "SELECT date, total_high, daily_new FROM new_high WHERE date >= ? ORDER BY date",
+        (dates[-1],)
+    ).fetchall()
+    values = [r[1] for r in rows if r[1] is not None]
+    return {
+        'chart_id': 'new_high',
+        'title': '百日新高分析',
+        'date_range': f"{dates[-1]} ~ {dates[0]}",
+        'data_points': len(rows),
+        'latest_total': rows[-1][1] if rows else 0,
+        'latest_daily_new': rows[-1][2] if rows else 0,
+        'avg_total': round(sum(values) / len(values), 2) if values else 0,
+        'max_total': max(values) if values else 0,
+        'min_total': min(values) if values else 0,
+        'trend': 'up' if len(values) >= 2 and values[-1] > values[0] else 'down',
+        'recent_10_days': [{'date': r[0], 'total': r[1], 'new': r[2]} for r in rows[-10:]],
+    }
+
+
+def _extract_sector_new_high(conn, analysis_date):
+    dates = _get_recent_dates(conn, 'sector_new_high', 'date', analysis_date, 30)
+    if not dates:
+        return {'error': '无数据'}
+    latest = dates[0]
+    rows = conn.execute(
+        "SELECT sector_name, total_high, daily_new FROM sector_new_high WHERE date = ? ORDER BY total_high DESC LIMIT 10",
+        (latest,)
+    ).fetchall()
+    return {
+        'chart_id': 'sector_new_high',
+        'title': '百日新高板块',
+        'latest_date': latest,
+        'date_range': f"{dates[-1]} ~ {dates[0]}",
+        'top10_sectors': [{'name': r[0], 'total': r[1], 'new': r[2]} for r in rows],
+    }
+
+
+def _extract_new_high_pie(conn, analysis_date):
+    return _extract_sector_new_high(conn, analysis_date)
+
+
+def _extract_emotion_limit(conn, analysis_date):
+    dates = _get_recent_dates(conn, 'market_sentiment', 'date', analysis_date, 60)
+    if not dates:
+        return {'error': '无数据'}
+    rows = conn.execute(
+        "SELECT date, limit_up, limit_down, rise_count, fall_count FROM market_sentiment WHERE date >= ? ORDER BY date",
+        (dates[-1],)
+    ).fetchall()
+    return {
+        'chart_id': 'emotion_limit',
+        'title': '上涨与下跌',
