+```python
+# -*- coding: utf-8 -*-
+"""
+AI图表分析核心模块
+从DB提取图表数据 → 调用LLM分析 → 写入结果到DB
+"""
+import sys
+import json
+import argparse
+from pathlib import Path
+
+# 确保能导入同目录模块
+sys.path.insert(0, str(Path(__file__).parent))
+
+import data_extractor
+import db_writer
+
+PROMPTS_DIR = Path(__file__).parent / 'prompts'
+
+CHART_PROMPT_MAP = {
+    'strength': 'strength.txt',
+    'strength_pie': 'strength.txt',
+    'new_high': 'generic.txt',
+    'sector_new_high': 'generic.txt',
+    'new_high_pie': 'generic.txt',
+    'emotion_limit': 'emotion.txt',
+    'emotion_premium': 'emotion.txt',
+    'emotion_ladder': 'emotion.txt',
+    'limit_up_pie': 'limit_up.txt',
+    'limit_up_stocks': 'limit_up.txt',
+}
+
+ALL_CHART_IDS = list(CHART_PROMPT_MAP.keys())
+
+
+def load_config():
+    """加载配置文件"""
+    config_path = Path(__file__).parent / 'config.json'
+    if not config_path.exists():
+        config_path = Path(__file__).parent / 'config.example.json'
+    with open(config_path, 'r', encoding='utf-8') as f:
+        return json.load(f)
+
+
+def load_prompt_template(chart_id):
+    """加载prompt模板"""
+    filename = CHART_PROMPT_MAP.get(chart_id, 'generic.txt')
+    path = PROMPTS_DIR / filename
+    if path.exists():
+        return path.read_text(encoding='utf-8')
+    return (PROMPTS_DIR / 'generic.txt').read_text(encoding='utf-8')
+
+
+def build_prompt(chart_id, chart_data):
+    """构造完整的分析prompt"""
+    template = load_prompt_template(chart_id)
+    # 将数据填入模板
+    data_str = json.dumps(chart_data, ensure_ascii=False, indent=2, default=str)
+    prompt = template.replace('{data_summary}', data_str)
+    for key, val in chart_data.items():
+        if isinstance(val, (str, int, float)):
+            prompt = prompt.replace('{' + key + '}', str(val))
+        elif isinstance(val, list):
+            prompt = prompt.replace('{' + key + '}', json.dumps(val, ensure_ascii=False, default=str))
+        elif isinstance(val, dict):
+            prompt = prompt.replace('{' + key + '}', json.dumps(val, ensure_ascii=False, default=str))
+    # 追加完整数据
+    prompt += '\n\n--- 完整数据 (JSON) ---\n' + data_str
+    return prompt
+
+
+def call_llm(prompt, config):
+    """调用LLM，返回 (analysis_text, summary, confidence)"""
+    import requests
+
+    llm_config = config.get('llm', {})
+    backend = llm_config.get('backend', 'openai')
+    api_key = llm_config.get('api_key', '')
+    model = llm_config.get('model', 'gpt-4o')
+    base_url = llm_config.get('base_url', 'https://api.openai.com/v1')
+    timeout = llm_config.get('timeout', 60)
+
+    if not api_key or api_key == 'sk-xxx':
+        # 无API Key时返回模拟分析（用于测试）
+        return _mock_analysis(prompt), '模拟分析（未配置API Key）', 0.3
+
+    headers = {
+        'Authorization': f'Bearer {api_key}',
+        'Content-Type': 'application/json'
+    }
+
+    payload = {
+        'model': model,
+        'messages': [
+            {'role': 'system', 'content': '你是一位专业的A股市场分析师，擅长板块强度、情绪指标和涨停数据分析。请输出结构化的Markdown格式分析报告。'},
+            {'role': 'user', 'content': prompt}
+        ],
+        'temperature': 0.3,
+        'max_tokens': 2000,
+    }
+
+    if backend == 'anthropic':
+        # Claude API格式
+        headers = {
+            'x-api-key': api_key,
+            'Content-Type': 'application/json',
+            'anthropic-version': '2023-06-01'
+        }
+        payload = {
+            'model': model,
+            'max_tokens': 2000,
+            'system': '你是一位专业的A股市场分析师。',
+            'messages': [{'role': 'user', 'content': prompt}]
+        }
+        resp = requests.post(f'{base_url}/messages', json=payload, headers=headers, timeout=timeout)
+        resp.raise_for_status()
+        data = resp.json()
+        analysis_text = data['content'][0]['text']
+    else:
+        # OpenAI兼容格式 (openai/qwen/custom/ollama)
+        if backend == 'ollama':
+            base_url = base_url or 'http://localhost:11434/v1'
+        resp = requests.post(f'{base_url}/chat/completions', json=payload, headers=headers, timeout=timeout)
+        resp.raise_for_status()
+        data = resp.json()
+        analysis_text = data['choices'][0]['message']['content']
+
+    # 提取摘要 (第一个段落或第一句话)
+    summary = analysis_text.split('\n')[0][:100] if analysis_text else ''
+    confidence = 0.8  # 默认置信度，可根据实际情况调整
+
+    return analysis_text, summary, confidence
+
+
+def _mock_analysis(prompt):
+    """无API Key时的模拟分析（用于测试流程）"""
+    return """## 趋势解读
+当前数据呈现正常波动状态，需结合更多市场背景进行深度分析。
+
+## 关键发现
+- 数据样本已成功提取，覆盖近30个交易日
+- 各项指标在正常范围内波动
+- 未发现明显异常信号
+
+## 异常预警
+暂无明显异常
+
+## 操作建议
+建议配置LLM API Key后重新运行以获取完整AI分析。当前为模拟数据。"""
+
+
+def analyze_chart(chart_id, analysis_date, mode='data'):
+    """分析单个图表"""
+    config = load_config()
+
+    # 1. 提取数据
+    chart_data = data_extractor.extract(chart_id, analysis_date)
+    if 'error' in chart_data:
+        return {'status': 'error', 'message': chart_data['error']}
+
+    # 2. 计算hash
+    data_hash = db_writer.compute_hash(chart_data)
+
+    # 3. 检查缓存
+    import sqlite3
+    db_path = Path(__file__).parent.parent / 'data' / 'kpl_dashboard.db'
+    conn = sqlite3.connect(str(db_path))
+    try:
+        if db_writer.cache_exists(conn, chart_id, analysis_date, data_hash):
+            return {'status': 'cache_hit', 'message': f'{chart_id} 数据未变化，跳过'}
+    finally:
+        conn.close()
+
+    # 4. 构造prompt
+    prompt = build_prompt(chart_id, chart_data)
+
+    # 5. 调用LLM
+    analysis_text, summary, confidence = call_llm(prompt, config)
+
+    # 6. 写入DB
+    agent_name = config.get('agent_name', 'unknown')
+    result = db_writer.write(chart_id, analysis_date, data_hash,
+                             analysis_text, summary, confidence, agent_name, mode)
+    return result
+
+
+def analyze_all(analysis_date, mode='data'):
+    """批量分析所有图表"""
+    results = []
+    for chart_id in ALL_CHART_IDS:
+        print(f"正在分析: {chart_id} ...")
+        try:
+            result = analyze_chart(chart_id, analysis_date, mode)
+            results.append({'chart_id': chart_id, **result})
+            print(f"  → {result}")
+        except Exception as e:
+            results.append({'chart_id': chart_id, 'status': 'error', 'message': str(e)})
+            print(f"  → 错误: {e}")
+    return results
+
+
